//! SASLprep (RFC 4013): the stringprep profile SCRAM applies to passwords
//! (RFC 5802 §2.2), so `"I\u{AD}X"`, `"\u{2168}"` and `"IX"` are one password
//! and a decomposed `"a\u{300}"` is the same as `"à"`.
//!
//! Map (B.1 removed, C.1.2 spaces → U+0020), normalize with NFKC, refuse the
//! prohibited characters (C.1.2–C.9 and, for stored strings, the code points
//! Unicode 3.2 left unassigned), and check bidirectional text. The tables are
//! Unicode 3.2, as RFC 3454 fixes, generated by `tools/gen_saslprep.py`.
//!
//! What a refusal means is the caller's: libpq (and the PostgreSQL server)
//! fall back to the password as given; MongoDB drivers refuse to log in.

use crate::saslprep_tables::{CCC, COMPOSE, DECOMPOSE, L_CAT, MAP_TO_NOTHING, NON_ASCII_SPACE, PROHIBITED, RAND_AL_CAT};
use std::borrow::Cow;
use std::fmt;

/// Why a string has no SASLprep form.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SaslPrepError {
    /// A prohibited or (in Unicode 3.2) unassigned character.
    Prohibited(char),
    /// Right-to-left text that breaks RFC 3454 §6 (mixed with left-to-right
    /// characters, or not starting and ending with a right-to-left one).
    Bidi,
}

impl fmt::Display for SaslPrepError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Prohibited(c) => write!(f, "SASLprep: prohibited character U+{:04X}", u32::from(*c)),
            Self::Bidi => f.write_str("SASLprep: invalid bidirectional text"),
        }
    }
}

impl std::error::Error for SaslPrepError {}

fn in_ranges(table: &[(u32, u32)], c: char) -> bool {
    let c = u32::from(c);
    table.binary_search_by(|&(lo, hi)| if hi < c { std::cmp::Ordering::Less } else if lo > c { std::cmp::Ordering::Greater } else { std::cmp::Ordering::Equal }).is_ok()
}

/// The SASLprep form of `s` ("stored strings": unassigned code points are
/// refused). Printable ASCII is returned as is, without copying.
pub fn saslprep(s: &str) -> Result<Cow<'_, str>, SaslPrepError> {
    if s.bytes().all(|b| (0x20..0x7F).contains(&b)) {
        return Ok(Cow::Borrowed(s));
    }
    // 1. Map.
    let mapped: String = s
        .chars()
        .filter(|&c| !in_ranges(MAP_TO_NOTHING, c))
        .map(|c| if in_ranges(NON_ASCII_SPACE, c) { ' ' } else { c })
        .collect();
    // 2. Normalize.
    let out = nfkc(&mapped);
    // 3. Prohibit.
    if let Some(c) = out.chars().find(|&c| in_ranges(PROHIBITED, c)) {
        return Err(SaslPrepError::Prohibited(c));
    }
    // 4. Bidirectional text.
    if out.chars().any(|c| in_ranges(RAND_AL_CAT, c)) {
        let ends = |c: Option<char>| c.is_some_and(|c| in_ranges(RAND_AL_CAT, c));
        if out.chars().any(|c| in_ranges(L_CAT, c)) || !ends(out.chars().next()) || !ends(out.chars().last()) {
            return Err(SaslPrepError::Bidi);
        }
    }
    Ok(Cow::Owned(out))
}

// --- NFKC (Unicode 3.2) ----------------------------------------------------------

const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

fn ccc(c: char) -> u8 {
    CCC.binary_search_by_key(&u32::from(c), |&(cp, _)| cp).map_or(0, |i| CCC[i].1)
}

fn decompose(c: char, out: &mut Vec<char>) {
    let cp = u32::from(c);
    if (S_BASE..S_BASE + S_COUNT).contains(&cp) {
        let s = cp - S_BASE;
        let jamo = |v| char::from_u32(v).expect("a Hangul jamo");
        out.push(jamo(L_BASE + s / N_COUNT));
        out.push(jamo(V_BASE + s % N_COUNT / T_COUNT));
        if !s.is_multiple_of(T_COUNT) {
            out.push(jamo(T_BASE + s % T_COUNT));
        }
        return;
    }
    match DECOMPOSE.binary_search_by_key(&cp, |&(k, _)| k) {
        Ok(i) => out.extend(DECOMPOSE[i].1.chars()),
        Err(_) => out.push(c),
    }
}

fn compose(a: char, b: char) -> Option<char> {
    let (a, b) = (u32::from(a), u32::from(b));
    if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
        return char::from_u32(S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&a) && (a - S_BASE).is_multiple_of(T_COUNT) && (T_BASE + 1..T_BASE + T_COUNT).contains(&b) {
        return char::from_u32(a + (b - T_BASE));
    }
    COMPOSE.binary_search_by_key(&(a, b), |&(x, y, _)| (x, y)).ok().and_then(|i| char::from_u32(COMPOSE[i].2))
}

/// Unicode normalization form KC.
pub(crate) fn nfkc(s: &str) -> String {
    let mut d = Vec::with_capacity(s.len());
    for c in s.chars() {
        decompose(c, &mut d);
    }
    // Canonical order: a stable sort of each run of combining marks by class.
    let mut i = 0;
    while i < d.len() {
        if ccc(d[i]) == 0 {
            i += 1;
            continue;
        }
        let start = i;
        while i < d.len() && ccc(d[i]) != 0 {
            i += 1;
        }
        d[start..i].sort_by_key(|&c| ccc(c));
    }
    // Canonical composition.
    let mut out: Vec<char> = Vec::with_capacity(d.len());
    let mut starter: Option<usize> = None;
    let mut last_ccc = 0u8;
    for c in d {
        let cc = ccc(c);
        if let Some(si) = starter {
            let adjacent = si + 1 == out.len();
            let blocked = !adjacent && (last_ccc == 0 || last_ccc >= cc);
            if !blocked {
                if let Some(composed) = compose(out[si], c) {
                    out[si] = composed;
                    continue;
                }
            }
        }
        if cc == 0 {
            starter = Some(out.len());
        }
        last_ccc = cc;
        out.push(c);
    }
    out.into_iter().collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rfc4013_examples() {
        // RFC 4013 §3.
        assert_eq!(saslprep("I\u{AD}X").unwrap(), "IX", "soft hyphen mapped to nothing");
        assert_eq!(saslprep("user").unwrap(), "user", "no transformation");
        assert_eq!(saslprep("USER").unwrap(), "USER", "case preserved");
        assert_eq!(saslprep("\u{AA}").unwrap(), "a", "output is NFKC");
        assert_eq!(saslprep("\u{2168}").unwrap(), "IX", "output is NFKC");
        assert_eq!(saslprep("\u{7}"), Err(SaslPrepError::Prohibited('\u{7}')));
        assert_eq!(saslprep("\u{627}\u{31}"), Err(SaslPrepError::Bidi));
    }

    #[test]
    fn passwords_people_type() {
        // Vietnamese: precomposed stays; decomposed (as some keyboards send it) composes.
        assert_eq!(saslprep("mậtkhẩu").unwrap(), "mậtkhẩu");
        assert_eq!(saslprep("ma\u{323}\u{302}tkha\u{302}\u{309}u").unwrap(), "mậtkhẩu", "dot below and circumflex in either order");
        assert_eq!(saslprep("ma\u{302}\u{323}tkha\u{302}\u{309}u").unwrap(), "mậtkhẩu");
        // Marks of the same class keep their order: hook-then-circumflex is another string.
        assert_ne!(saslprep("kha\u{309}\u{302}u").unwrap(), "khẩu");
        // Non-ASCII spaces, ligatures, full-width forms.
        assert_eq!(saslprep("a\u{A0}b\u{3000}c").unwrap(), "a b c");
        assert_eq!(saslprep("\u{FB01}le").unwrap(), "file");
        assert_eq!(saslprep("ｐａｓｓ１").unwrap(), "pass1");
        // Hangul: jamo compose into syllables; syllables are kept.
        assert_eq!(saslprep("\u{1100}\u{1161}\u{11A8}").unwrap(), "\u{AC01}");
        assert_eq!(saslprep("한국어").unwrap(), "한국어");
        // Right-to-left text on its own is fine.
        assert_eq!(saslprep("\u{5D0}\u{5D1}").unwrap(), "\u{5D0}\u{5D1}");
        // Unassigned in Unicode 3.2 (an emoji), and a private-use character.
        assert_eq!(saslprep("pw\u{1F600}"), Err(SaslPrepError::Prohibited('\u{1F600}')));
        assert_eq!(saslprep("pw\u{E000}"), Err(SaslPrepError::Prohibited('\u{E000}')));
        // ASCII is untouched and not copied; a tab is a control character.
        assert!(matches!(saslprep("pencil"), Ok(Cow::Borrowed("pencil"))));
        assert_eq!(saslprep("a\tb"), Err(SaslPrepError::Prohibited('\t')));
    }

    #[test]
    fn nfkc_blocking_and_singletons() {
        // A mark of the same class between the base and a second mark blocks it.
        assert_eq!(nfkc("a\u{301}\u{301}"), "\u{E1}\u{301}");
        // Composition exclusions and singletons stay decomposed / map.
        assert_eq!(nfkc("\u{2126}"), "\u{3A9}", "OHM SIGN → OMEGA");
        assert_eq!(nfkc("\u{958}"), "\u{915}\u{93C}", "excluded from composition");
        assert_eq!(nfkc("\u{212B}"), "\u{C5}", "ANGSTROM SIGN → Å");
    }
}

